import{G as e,K as t,n,ot as r}from"./chunks/framework.C8_jer4d.js";var i=JSON.parse(`{"title":"Assess the toolkit upgrade impact","description":"","frontmatter":{"title":"Assess the toolkit upgrade impact","prev":{"text":"Lab 2: Overview"},"next":{"text":"Lab 3: Overview"}},"headers":[],"relativePath":"baw-lab/toolkit-dependencies/challenge.md","filePath":"baw-lab/toolkit-dependencies/challenge.md"}`),a={name:`baw-lab/toolkit-dependencies/challenge.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h2 id="🧱-clue-1-the-shared-foundation" tabindex="-1">🧱 Clue 1 - The Shared Foundation <a class="header-anchor" href="#🧱-clue-1-the-shared-foundation" aria-label="Permalink to “🧱 Clue 1 - The Shared Foundation”">​</a></h2><blockquote><p><em>&quot;Toolkits make reuse simple. But when different parts of your application quietly depend on different versions of the same foundation, upgrading becomes a minefield.&quot;</em></p></blockquote><h3 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h3><p>The <code>baw-toolkit-analyzer</code> skill analyzes the toolkit dependencies of a process application from its TWX export. It does not need a connection to a BAW server. When you give it a TWX file, it:</p><ul><li>Reads the toolkit dependencies that the application declares, with the snapshot of each toolkit.</li><li>Opens the toolkits that are embedded in the TWX and reads which toolkits they depend on in turn.</li><li>Scans the application&#39;s artifacts to find which of them use items from each toolkit.</li><li>Checks the result for conflicting snapshots, unused toolkits, and references to a toolkit that is no longer declared.</li></ul><p>Bob combines deterministic static dependency scanning of the TWX with natural language reasoning, allowing you to not only generate comprehensive dependency graphs but also query complex impact questions conversationally.</p><p>By default, the skill runs a full analysis of all toolkit dependencies. In this lab you run the full analysis first, then drill down conversationally in Challenge 3.</p><p>The lab application is <code>ClaimsProcessing.twx</code>, an insurance claims process application. It declares four toolkits: System Data (<code>TWSYS</code>), ClaimsUtilities (<code>CU</code>), RulesEngine (<code>RE</code>), and LegacyReports (<code>LR</code>).</p><hr><h3 id="🤖-challenge-1-—-ask-bob-to-analyze-the-toolkit-dependencies" tabindex="-1">🤖 Challenge 1 — Ask Bob to analyze the toolkit dependencies <a class="header-anchor" href="#🤖-challenge-1-—-ask-bob-to-analyze-the-toolkit-dependencies" aria-label="Permalink to “🤖 Challenge 1 — Ask Bob to analyze the toolkit dependencies”">​</a></h3><ol><li><p>In the Bob IDE Explorer panel, expand the <code>lab-2/</code> folder and confirm <code>ClaimsProcessing.twx</code> is present. Do <strong>not</strong> open, rename, or move it.</p></li><li><p>Open the Bob Chat Panel with <strong>Option + Cmd + B</strong> (macOS) or <strong>Ctrl + Alt + B</strong> (Windows/Linux), or click the <strong>Bob icon</strong> beside the navigation bar.</p></li><li><p>Start a <strong>new chat</strong> by clicking the <strong>+</strong> (New Chat) icon at the top of the panel.</p></li><li><p>Click the <strong>+</strong> at the bottom left of the chat input, select <strong>IBM BAW Author</strong> under <strong>Modes</strong>, and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please analyze the toolkit dependencies of ClaimsProcessing.twx.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Write any output to docs/lab2-output/</span></span></code></pre></div></li><li><p>Press <strong>Enter</strong> and click <strong>Approve skill tools for task</strong> when prompted. Approve each action individually as Bob runs the analysis and writes the report.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">💡 <strong>Tip:</strong> The TWX file is the only input the skill needs. Bob defaults to full analysis automatically.</p></div><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li>Bob shows a summary of the toolkit dependencies in the chat.</li><li>In the Explorer, the folder <code>docs/lab2-output/</code> exists and contains <code>toolkit-dependency-report.md</code> and <code>toolkit-dependency-report.json</code>.</li></ul></div><hr><h3 id="📖-challenge-2-—-read-the-report-and-judge-the-upgrade-impact" tabindex="-1">📖 Challenge 2 — Read the report and judge the upgrade impact <a class="header-anchor" href="#📖-challenge-2-—-read-the-report-and-judge-the-upgrade-impact" aria-label="Permalink to “📖 Challenge 2 — Read the report and judge the upgrade impact”">​</a></h3><p>Imagine you are about to promote <code>ClaimsProcessing</code> to production. Before you change or upgrade any toolkit, read the report to find out what is at risk.</p><ol><li>In the Explorer, expand <code>docs/lab2-output/</code> and open <code>toolkit-dependency-report.md</code>.</li><li>Open the Markdown preview to see the dependency graph rendered: right-click the editor tab and choose <strong>Open Preview</strong>. Alternatively, click once inside the report text in the editor, so the editor has focus rather than the Explorer, and press <strong>Cmd + Shift + V</strong> (macOS) / <strong>Ctrl + Shift + V</strong> (Windows/Linux).</li><li>Locate these sections of the report: <ul><li><strong>1. Executive Summary</strong> — the number of direct and transitive dependencies and the list of detected issues</li><li><strong>2. Direct Dependencies Overview</strong> — one row per declared toolkit, with its snapshot and usage status</li><li><strong>3. Toolkit Usage Breakdown</strong> — for each toolkit, the artifacts that use it and what they use</li><li><strong>4. Visual Dependency Graph</strong> — the Mermaid graph of direct and transitive dependencies</li><li><strong>5. Transitive Dependencies</strong> — the toolkits that come in through <code>CU</code>, <code>RE</code>, and <code>LR</code></li><li><strong>6. Recommendations &amp; Action Items</strong> — what to do about each issue</li></ul></li><li>Use the report to answer these questions: <ul><li>How many issues does the Executive Summary list, and of which types?</li><li>Which toolkit has no references from any artifact, and is therefore a candidate to remove?</li><li>Which two artifacts contain a reference that cannot be resolved to a declared toolkit?</li><li>Which toolkit is referenced at two different snapshots, and through which direct toolkits?</li></ul></li><li>In the dependency graph, follow the lines from <code>ClaimsProcessing</code> through <code>CU</code> and <code>RE</code> and confirm where the two snapshots meet.</li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Checkpoint</strong></p><ul><li>The Executive Summary lists <strong>4 issues</strong>: two dangling references, one snapshot conflict, and one unused toolkit.</li><li><code>LegacyReports</code> (<code>LR</code>) is shown as having no direct references, and the recommendations advise verifying and then removing it.</li><li>The two dangling references are in <code>Run Fraud Detection</code> and <code>Notify Supervisor Adjuster Overdue</code>.</li><li><code>SharedTypes</code> (<code>ST</code>) appears at snapshot <code>2024-03</code> via <code>CU</code> and at <code>2025-01</code> via <code>RE</code>.</li><li>The dependency graph renders as a diagram in the Markdown preview.</li></ul></div><hr><h3 id="🔎-challenge-3-—-drill-down-into-a-toolkit" tabindex="-1">🔎 Challenge 3 — Drill down into a toolkit <a class="header-anchor" href="#🔎-challenge-3-—-drill-down-into-a-toolkit" aria-label="Permalink to “🔎 Challenge 3 — Drill down into a toolkit”">​</a></h3><p>Before you upgrade <code>RulesEngine</code>, you need to know exactly which artifacts depend on it. Ask Bob in the same chat.</p><ol><li><p>Stay in the same chat. Check that <strong>IBM BAW Author</strong> is still the active mode (click the <strong>+</strong> at the bottom left of the chat input; the active mode has a checkmark under <strong>Modes</strong>), and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Which artifacts in ClaimsProcessing.twx use the RulesEngine toolkit?</span></span></code></pre></div></li><li><p>Press <strong>Enter</strong> and approve each action as it appears.</p><div class="tip custom-block"><p class="custom-block-title">ℹ️ <strong>NOTE</strong></p><p>Notice how you stayed in the same chat and asked in plain language. Bob maintains conversation context, recognizing the target toolkit and automatically switching from the initial <code>full</code> analysis mode to a targeted <code>where-used</code> drill-down without requiring CLI flags or manual reconfiguration.</p></div></li><li><p>Read Bob&#39;s answer and review the regenerated report:</p><ul><li>In the chat, Bob provides a detailed analysis naming the declared dependency on <code>RulesEngine</code> (<code>RE</code>) and each artifact using it (<code>ClaimRequest</code> and <code>Calculate Settlement Amount</code>).</li><li>Open <code>toolkit-dependency-report.md</code> in the Explorer to confirm the report has been dynamically regenerated and ends with a <strong>Where Used: <code>RE</code></strong> section recording the drill-down target.</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">✅ <strong>Final Checkpoint</strong></p><ul><li>Bob lists two artifacts that use <code>RulesEngine</code>: the business object <code>ClaimRequest</code> and the service flow <code>Calculate Settlement Amount</code> (which uses <code>CalculateDeductible</code>).</li><li>You can state the upgrade impact: a change to <code>RulesEngine</code> affects those two artifacts, and updating it also touches the <code>SharedTypes</code> snapshot conflict you found in Challenge 2.</li></ul></div>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};